"""사용자 auto-generated file 을 scope 로 조회하기."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import UTC, datetime
from typing import override

import pytest

from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AutoGeneratedFileFilter,
    AutoGeneratedFileOrder,
    ScopedSearchAutoGeneratedFilesInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import (
    SearchAutoGeneratedFilesPayload,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import (
    AutoGeneratedFileOrderField,
    AutoGeneratedFileScope,
    AutoGeneratedFileScopeType,
)
from ai.backend.common.dto.manager.v2.common import OrderDirection
from ai.backend.common.dto.manager.v2.rbac.types import UUIDScope
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.errors.permission import NotEnoughPermission
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import (
    Answered,
    Given,
    Held,
    Same,
    SameAs,
    Says,
    Scenario,
    Then,
    Verdict,
    When,
)
from bai_scenario.components.answers import MissingResponse, TheCallIsRefused
from bai_scenario.components.auto_generated_file import (
    A_FILE_NOT_DEFAULT,
    ANOTHER_DEFAULT_FILE,
    CONFIG_PERMISSION,
    THE_DEFAULT_FILE,
    AUserAndTheirOwnConfig,
    SomeoneWithTheirOwnConfig,
)
from bai_scenario.components.domain import WrittenByThisRun
from bai_scenario.runner.acting import ActingAs
from bai_scenario.runner.planting import TestSeedingSession
from bai_scenario.runner.steps import run_scenario

type Laid = AUserAndTheirOwnConfig
type Answer = SearchAutoGeneratedFilesPayload
type SearchStep = Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]

THE_OWNER = Says("파일 주인의 id", english="the owner's id")
PAGE_SIZE = 10

# 심는 순서: default 로 지정된 .vimrc, default 로 지정되지 않은 .vimrc, default 로 지정된 .bashrc
FILES_TO_SEARCH = (THE_DEFAULT_FILE, A_FILE_NOT_DEFAULT, ANOTHER_DEFAULT_FILE)


@dataclass(frozen=True)
class ListingTheDefaultFilesByPath(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """default 로 지정된 자기 파일만 path 오름차순으로, 한 페이지만큼 조회한다."""

    @override
    def operation(self) -> str:
        return "scoped_search"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 자기 scope 의 auto-generated file 중 default 로 지정된 것만 "
            f"path 오름차순으로 {PAGE_SIZE}개까지 조회합니다",
            english=(
                f"{laid.owner.username} lists up to {PAGE_SIZE} auto-generated files of their own "
                "scope that are set as default, ordered by path"
            ),
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            return await adapter.scoped_search(
                ScopedSearchAutoGeneratedFilesInput(
                    scope=AutoGeneratedFileScope(user=[UUIDScope(value=laid.owner.id)]),
                    filter=AutoGeneratedFileFilter(is_default=True),
                    order=[
                        AutoGeneratedFileOrder(
                            field=AutoGeneratedFileOrderField.PATH, direction=OrderDirection.ASC
                        )
                    ],
                    limit=PAGE_SIZE,
                )
            )


@dataclass(frozen=True)
class TheDefaultFilesInPathOrder(Then[Laid, Answer]):
    started: datetime

    @override
    def says(self) -> str:
        return Says(
            "default 로 지정된 자기 파일 둘만 path 순서로 실린 한 페이지가 응답으로 옵니다",
            english=(
                "one page holding only their two files set as default, in path order, comes back"
            ),
        )

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        page = answered.response
        if page is None:
            return [MissingResponse(answered.raised)]
        verdicts: list[Verdict] = [
            Same("total_count", page.total_count, 2),
            Same("has_next_page", page.has_next_page, False),
            Same("has_previous_page", page.has_previous_page, False),
            Same("items.length", len(page.items), 2),
        ]
        if len(page.items) != 2:
            return verdicts
        # path 오름차순: .bashrc 가 .vimrc 앞에 온다.
        expected = (laid.files[2], laid.files[0])
        for at, (seeded, node) in enumerate(zip(expected, page.items, strict=True)):
            name = Says(
                f"심어 둔 default 로 지정된 {seeded.path} 파일",
                english=f"the {seeded.path} file seeded as default",
            )
            verdicts.extend([
                Held(f"items[{at}].id", node.id, SameAs(seeded.id, name)),
                Held(f"items[{at}].entity_id", node.entity_id, SameAs(seeded.id, name)),
                Same(
                    f"items[{at}].scope_type",
                    str(node.scope_type),
                    str(AutoGeneratedFileScopeType.USER),
                ),
                Held(f"items[{at}].scope_id", node.scope_id, SameAs(laid.owner.id, THE_OWNER)),
                Same(f"items[{at}].path", node.path, seeded.path),
                Same(f"items[{at}].permission", node.permission, CONFIG_PERMISSION),
                Same(f"items[{at}].is_default", node.is_default, True),
                Held(f"items[{at}].created_at", node.created_at, WrittenByThisRun(self.started)),
                Held(f"items[{at}].updated_at", node.updated_at, WrittenByThisRun(self.started)),
            ])
        return verdicts


@dataclass(frozen=True)
class AUserListsTheirDefaultFiles(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    started: datetime

    @override
    def summary(self) -> str:
        return "a-user-granted-read-lists-their-auto-generated-files-set-as-default"

    @override
    def describe(self) -> str:
        return Says(
            "READ 를 받은 사용자가 자기 scope 에서 default 로 지정된 auto-generated file 을 path "
            "오름차순으로 한 페이지 조회하면, default 로 지정되지 않은 파일과 다른 사용자의 파일은 "
            "빠지고 자기 파일 둘만 path 순서로 옵니다",
            english=(
                "when a user holding READ lists the auto-generated files of their own scope that "
                "are set as default, ordered by path and limited to one page, their file not set "
                "as default and another user's file are left out, and only their two files come "
                "back in path order"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.READ,), files=FILES_TO_SEARCH, stranger_file=True
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return ListingTheDefaultFilesByPath()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheDefaultFilesInPathOrder(started=self.started)


@dataclass(frozen=True)
class AUserGrantedNothingMayNotList(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-may-not-list-auto-generated-files"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 scope 의 auto-generated file 을 조회하려 하면, 권한 "
            "부족으로 거부됩니다",
            english=(
                "a user holding no permission who tries to list the auto-generated files of "
                "their own scope is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(files=(THE_DEFAULT_FILE,))

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return ListingTheDefaultFilesByPath()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(NotEnoughPermission)


SCENARIOS: list[SearchStep] = [
    AUserListsTheirDefaultFiles(started=datetime.now(UTC)),
    AUserGrantedNothingMayNotList(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_v2_search(
    scenario: SearchStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
